export const shuffle = <T>( list: T[] ) => {
    let n = list.length;
    while (n > 1) {
      n--;
      let k = Math.floor( Math.random() * ( n + 1 ) );
    //   let k = Math.random() + (n + 1);
      let data = list[k];
      list[k] = list[n];
      list[n] = data;
    }
};